const base={maxNodes:3500,maxDepth:48,memoryBudgetMb:512,ttMode:'pattern-tt',enableRzPruning:true,enableFastCaptureOrdering:true,enableProgressiveWidening:true,wideningBaseK:8,deterministicMode:true,koRule:'SSK',attackerAllowKo:false,defenderAllowKo:true,useProblemDefaultKo:true};
for(const [id,first,qs] of [['chao_vol1_p060','rs',['rp','sq','rr','sr','ps']],['chao_vol2_p162','sr',['sp','sq','ms','os','ps','qs','rs','ss']]]){
const p=cat.find(x=>x.id===id);const ctx=S.buildProofContext(p,base); const c=x=>x==='pass'?-1:sgfToCoord(x,19);let spent=0,slice=0;
for(const src of ['pass',...qs]){const limit=src==='pass'?3500:slice;const pos=S.buildInitialPosition(p,ctx);if(!pos.playMove(c(first)).legal||!pos.playMove(c(src)).legal)throw Error('trace');
const report=new S({...base,maxNodes:limit}).solveFromPosition(p,pos,ctx);spent+=report.numNodes;if(src==='pass'){if(report.rootStatus!=='PROVEN_WIN')throw Error('expected source');slice=Math.floor((3500-spent)/qs.length);}
const m=new M();const v=m.verifySerializedLProofJson(report.lproofJson,{problem:p,context:ctx,scope:'traced_within_rules'});const queries={};if(v.passed)for(const q of qs){const x=m.verifySubproofFragment({problem:p,context:ctx,report,targetPathMoves:[c(first),c(src)],targetDagNodeId:report.rootDagNodeId,queryPathMoves:[c(first),c(q)]});if(!x.sourceReceipt.passed) throw Error(x.sourceReceipt.message);queries[q]=x.queryReplayReceipt.errorCode;}
console.log(JSON.stringify({id,first,src,limit,n:report.numNodes,spent,status:report.rootStatus,best:report.bestMoveSgf,dag:report.proofDagNodes.length,check:v.errorCode,digest:v.canonicalDagChecksum,queries}));}
if(spent>3500)throw Error('overspend');
}

